import{_ as t,o as a,c as o,ah as i}from"./chunks/framework.DDXs_i7t.js";const p=JSON.parse('{"title":"Battle of the Experts: When Statistics Wash Corruption Away","description":"How a new WU Vienna study attempts to redefine the advertisement scandal involving Eva Dichand and Thomas Schmid.","frontmatter":{"title":"Battle of the Experts: When Statistics Wash Corruption Away","description":"How a new WU Vienna study attempts to redefine the advertisement scandal involving Eva Dichand and Thomas Schmid.","date":"2026-04-07T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-04-07-scientific-washing-dichand.md","filePath":"en/logbuch/2026-04-07-scientific-washing-dichand.md"}'),n={name:"en/logbuch/2026-04-07-scientific-washing-dichand.md"};function r(s,e,h,c,l,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="battle-of-the-experts-when-statistics-wash-corruption-away" tabindex="-1">Battle of the Experts: When Statistics Wash Corruption Away <a class="header-anchor" href="#battle-of-the-experts-when-statistics-wash-corruption-away" aria-label="Permalink to &quot;Battle of the Experts: When Statistics Wash Corruption Away&quot;">​</a></h1><p><strong>Vienna, April 7, 2026</strong> – While our project&#39;s virality index breaks the 500,000 mark, a scientific defensive battle is raging outside. The defense of Eva Dichand (<em>Heute</em>) presented a study from the Vienna University of Economics (WU) today, intended to prove that there was no &quot;benevolent reporting&quot; for Sebastian Kurz.</p><h2 id="the-scientific-washing-of-power" tabindex="-1">The &quot;Scientific Washing&quot; of Power <a class="header-anchor" href="#the-scientific-washing-of-power" aria-label="Permalink to &quot;The &quot;Scientific Washing&quot; of Power&quot;">​</a></h2><p>It is a fascinating phenomenon: 250,000 articles were processed by an AI to prove that <em>Heute</em> was actually neutral (or even pro-SPÖ). This is intended to invalidate the &quot;quid pro quo&quot; – the exchange of advertisement money for favorable coverage.</p><p>The defense led by Michael Rami and Johann Pauer is now on the offensive:</p><ul><li><strong>The Key Witness in the Crossfire:</strong> Thomas Schmid is to be directly confronted in a &quot;contradictory interrogation&quot; (a legal first).</li><li><strong>The Gap:</strong> If the statistics say &quot;everything&#39;s okay,&quot; how do we explain the chats in which Schmid celebrates advertisement allocation as a strategic tool?</li></ul><h2 id="the-analogy-to-the-horten-mystery" tabindex="-1">The Analogy to the &quot;Horten Mystery&quot; <a class="header-anchor" href="#the-analogy-to-the-horten-mystery" aria-label="Permalink to &quot;The Analogy to the &quot;Horten Mystery&quot;&quot;">​</a></h2><p>In our project, we examine the &quot;Horten Logic&quot;: Whoever has the money defines the truth. Today, this truth is no longer just underpinned by simple advertisements, but by complex scientific reports.</p><p>We are integrating this &quot;Battle of the Experts&quot; as a new element in <strong>Part 4 of our screenplay</strong>. It&#39;s about the question: Can a statistic overwrite the moral reality of chats?</p><p><em>The index of attention continues to rise. Truth is being digitally renegotiated.</em></p><hr><p>👈 <a href="/en/logbuch/">Back to Logbook</a> 🔮 <a href="/en/orakel.html">Consult the Oracle for the Truth</a></p>',12)])])}const f=t(n,[["render",r]]);export{p as __pageData,f as default};
